(40761, 'Exodus 39:3', 'Exodus', 39, 3, 'هغوی سره زر وټکول او نرۍ پاڼې یې ورڅخه جوړې کړې او تارونه یې ورڅخه پرې کړل چې په ابي، بانجاني او سرو وړیو او ښه کتان کې ورڅخه کار واخیستل شي، دا د یو ماهر کسبګر کار ؤ.', 'هغوی سره زر وتکول او نری پانې یې ورچخه جورې کرې او تارونه یې ورچخه پرې کرل چې په ابی، بانجانی او سرو وریو او شه کتان کې ورچخه کار واخیستل شی، دا د یو ماهر کسبګر کار و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40762, 'Exodus 39:4', 'Exodus', 39, 4, 'هغوی د سپېڅلي پېشبند دپاره د اوږې دوه تسمې جوړې کړې او د هغه په دواړو خواو باندې یې ونښلولې چې پېشبند ورسره وتړل شي.', 'هغوی د سپېچلی پېشبند دپاره د اوزې دوه تسمې جورې کرې او د هغه په دوارو خواو باندې یې ونشلولې چې پېشبند ورسره وترل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40763, 'Exodus 39:5', 'Exodus', 39, 5, 'ښه اوبدل شوی کمربند چې د هماغه موادو څخه جوړ شوی ؤ، هغه د سپېڅلي پېشبند سره ونښلول شو چې د یوې ټوټې په شان ښکاره شي. هغوی دا کار د څښتن د حکم سره سم چې موسی ته یې کړی ؤ، وکړ.', 'شه اوبدل شوی کمربند چې د هماغه موادو چخه جور شوی و، هغه د سپېچلی پېشبند سره ونشلول شو چې د یوې توتې په شان شکاره شی. هغوی دا کار د چشتن د حکم سره سم چې موسی ته یې کری و، وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40764, 'Exodus 39:6', 'Exodus', 39, 6, 'هغوی د عقیقو تیږې په هغو ځایونو کې ولګولې چې د سرو زرو د قابونو په شان جوړ شوي دي او په هغو باندې یې د مهر په شان د یعقوب د زامنو د نومونو نقش وویست.', 'هغوی د عقیقو تیزې په هغو جایونو کې ولګولې چې د سرو زرو د قابونو په شان جور شوی دی او په هغو باندې یې د مهر په شان د یعقوب د زامنو د نومونو نقش وویست.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40765, 'Exodus 39:7', 'Exodus', 39, 7, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، هغوی هغه تیږې د سپېڅلي پېشبند د اوږې په تسمو باندې ولګولې چې د اسراییلو د دولسو قبیلو استازیتوب وکړي.', 'لکه چنګه چې چشتن موسی ته حکم کری و، هغوی هغه تیزې د سپېچلی پېشبند د اوزې په تسمو باندې ولګولې چې د اسراییلو د دولسو قبیلو استازیتوب وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40766, 'Exodus 39:8', 'Exodus', 39, 8, 'هغوی سینه پوښ د هماغو موادو څخه جوړ کړ چې سپېڅلی پېشبند ورڅخه جوړ شوی ؤ او هماغسې ګلدوزي شو.', 'هغوی سینه پوش د هماغو موادو چخه جور کر چې سپېچلی پېشبند ورچخه جور شوی و او هماغسې ګلدوزی شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40767, 'Exodus 39:9', 'Exodus', 39, 9, 'هغه څلور کنجه ؤ، دوه ویشت سانتي اوږد او دوه ویشت سانتي پلن ؤ او دوه قاته ؤ.', 'هغه چلور کنجه و، دوه ویشت سانتی اوزد او دوه ویشت سانتی پلن و او دوه قاته و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40768, 'Exodus 39:10', 'Exodus', 39, 10, 'بیا هغوی په هغه باندې څلور قطاره قیمتي تیږې ولګولې. په لومړي قطار کې یې یو یاقوت، یو زیړ یاقوت او یو لعل ولګاوه،', 'بیا هغوی په هغه باندې چلور قطاره قیمتی تیزې ولګولې. په لومری قطار کې یې یو یاقوت، یو زیر یاقوت او یو لعل ولګاوه،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40769, 'Exodus 39:11', 'Exodus', 39, 11, 'په دوهم قطار کې یې یو زمرد، یوه د لاجوردو تیږه او یو الماس ولګاوه،', 'په دوهم قطار کې یې یو زمرد، یوه د لاجوردو تیزه او یو الماس ولګاوه،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40770, 'Exodus 39:12', 'Exodus', 39, 12, 'په درېم قطار کې یې یوه فیروزه، یو سپین عقیق او یو بانجاني یاقوت ولګاوه،', 'په درېم قطار کې یې یوه فیروزه، یو سپین عقیق او یو بانجانی یاقوت ولګاوه،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40771, 'Exodus 39:13', 'Exodus', 39, 13, 'په څلورم قطار کې یې یو شینکی یاقوت، د عقیقو یوه تیږه او یو یشم ولګاوه. هغه په داسې ځایونو کې ولګول شول چې د سرو زرو د قابونو په شان جوړ شوي دي.', 'په چلورم قطار کې یې یو شینکی یاقوت، د عقیقو یوه تیزه او یو یشم ولګاوه. هغه په داسې جایونو کې ولګول شول چې د سرو زرو د قابونو په شان جور شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40772, 'Exodus 39:14', 'Exodus', 39, 14, 'هلته دولس تیږې وې، د یعقوب د زامنو د هر یو نوم دپاره یوه یوه تیږه، په هرې یوې کې د یو مهر په شان نقش ویستل شوی ؤ او د دولسو قبیلو څخه د یوې قبیلې نوم په کې ؤ.', 'هلته دولس تیزې وې، د یعقوب د زامنو د هر یو نوم دپاره یوه یوه تیزه، په هرې یوې کې د یو مهر په شان نقش ویستل شوی و او د دولسو قبیلو چخه د یوې قبیلې نوم په کې و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40773, 'Exodus 39:15', 'Exodus', 39, 15, 'هغوی د سینه پوښ دپاره د سوچه سرو زرو څخه داسې زنځیرونه جوړ کړل چې د یوې رسۍ په شان تاو شوي وو.', 'هغوی د سینه پوش دپاره د سوچه سرو زرو چخه داسې زنجیرونه جور کرل چې د یوې رسی په شان تاو شوی وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40774, 'Exodus 39:16', 'Exodus', 39, 16, 'دوه د سرو زرو د قابونو په شان ځایونه او دوه د سرو زرو کړۍ ګانې یې جوړې کړې او د سینه پوښ په پورتنیو کنجونو پورې یې ونښلولې.', 'دوه د سرو زرو د قابونو په شان جایونه او دوه د سرو زرو کری ګانې یې جورې کرې او د سینه پوش په پورتنیو کنجونو پورې یې ونشلولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40775, 'Exodus 39:17', 'Exodus', 39, 17, 'په دغو دوو کړیو باندې یې دوه د سرو زرو زنځیرونه وتړل،', 'په دغو دوو کریو باندې یې دوه د سرو زرو زنجیرونه وترل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40776, 'Exodus 39:18', 'Exodus', 39, 18, 'او د زنځیرونو دوه نور سرونه یې په هغو ځایونو باندې چې د سرو زرو د قابونو په شان وو، وتړل او په دې ډول یې د سپېڅلي پېشبند د اوږې د تسمو په مخکینۍ برخې باندې ونښلول.', 'او د زنجیرونو دوه نور سرونه یې په هغو جایونو باندې چې د سرو زرو د قابونو په شان وو، وترل او په دې دول یې د سپېچلی پېشبند د اوزې د تسمو په مخکینی برخې باندې ونشلول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40777, 'Exodus 39:19', 'Exodus', 39, 19, 'هغوی د سرو زرو دوه کړۍ ګانې جوړې کړې او د سینه پوښ په لاندېنیو کنجونو پورې یې په دنننۍ څنډې باندې د سپېڅلي پېشبند په څنګ کې ونښلولې.', 'هغوی د سرو زرو دوه کری ګانې جورې کرې او د سینه پوش په لاندېنیو کنجونو پورې یې په دنننی چندې باندې د سپېچلی پېشبند په چنګ کې ونشلولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40778, 'Exodus 39:20', 'Exodus', 39, 20, 'دوه نورې کړۍ ګانې یې جوړې کړې او د اوږې د تسمو په لاندېنۍ برخه کې یې ونښلولې چې د سپېڅلي پېشبند په مخکینۍ برخې باندې بخۍ ته نژدې او د سپېڅلي پېشبند د کمربند دپاسه وې.', 'دوه نورې کری ګانې یې جورې کرې او د اوزې د تسمو په لاندېنی برخه کې یې ونشلولې چې د سپېچلی پېشبند په مخکینی برخې باندې بخی ته نژدې او د سپېچلی پېشبند د کمربند دپاسه وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40779, 'Exodus 39:21', 'Exodus', 39, 21, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، هغوی د سینه پوښ کړۍ ګانې د سپېڅلي پېشبند د کړۍ ګانو سره په ابي مزي باندې وتړلې چې د کمربند سره وصل شي، ترڅو سینه پوښ د سپېڅلي پېشبند څخه لېرې نه شي.', 'لکه چنګه چې چشتن موسی ته حکم کری و، هغوی د سینه پوش کری ګانې د سپېچلی پېشبند د کری ګانو سره په ابی مزی باندې وترلې چې د کمربند سره وصل شی، ترچو سینه پوش د سپېچلی پېشبند چخه لېرې نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40780, 'Exodus 39:22', 'Exodus', 39, 22, 'هغه چپنه چې د سپېڅلي پېشبند لاندې اغوستل کېدله ټوله د ابي ټوکر څخه جوړه شوه.', 'هغه چپنه چې د سپېچلی پېشبند لاندې اغوستل کېدله توله د ابی توکر چخه جوره شوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40781, 'Exodus 39:23', 'Exodus', 39, 23, 'د هغې په منځ کې یې د سر دپاره یو سوری پرېښود او د سوري ګردچاپېره یې یوه غاړه وګنډله، ترڅو چپنه ونه شلیږي.', 'د هغې په منج کې یې د سر دپاره یو سوری پرېشود او د سوری ګردچاپېره یې یوه غاره وګندله، ترچو چپنه ونه شلیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_39_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
